package com.hongik.graduate.ai.experience;

import java.util.List;
import java.util.UUID;

/** Contract shared by quick entry, future chat and imports; v1, not generated by an LLM. */
public record ExperienceSummary(
        UUID experienceId, String title, String tagCode,
        String situation, String task, String action, String result,
        String role, String conflict, String learned,
        List<String> skills, List<String> keywords,
        List<SourceRef> evidenceSources, String schemaVersion, String origin
) {
    public static final String VERSION = "v1";

    public ExperienceSummary {
        if (experienceId == null || title == null || title.isBlank()
                || tagCode == null || tagCode.isBlank()
                || !VERSION.equals(schemaVersion)
                || origin == null || !List.of("USER", "MOCK", "AI").contains(origin)) {
            throw new IllegalArgumentException("invalid experience summary metadata");
        }
        skills = List.copyOf(skills == null ? List.of() : skills);
        keywords = List.copyOf(keywords == null ? List.of() : keywords);
        evidenceSources = List.copyOf(evidenceSources == null ? List.of() : evidenceSources);
        if (skills.size() > 30 || keywords.size() > 30 || evidenceSources.size() > 20
                || skills.stream().anyMatch(s -> s == null || s.isBlank())
                || keywords.stream().anyMatch(s -> s == null || s.isBlank() || s.length() > 80)) {
            throw new IllegalArgumentException("invalid experience summary tags");
        }
        for (String field : List.of(
                value(situation), value(task), value(action), value(result),
                value(role), value(conflict), value(learned))) {
            if (field.length() > 5000) {
                throw new IllegalArgumentException("experience summary field too long");
            }
        }
    }

    private static String value(String field) {
        return field == null ? "" : field;
    }

    public record SourceRef(UUID sourceId, String location, String quote) {
        public SourceRef {
            if (sourceId == null || location == null || location.isBlank()
                    || location.length() > 120 || quote == null
                    || quote.isBlank() || quote.length() > 1000) {
                throw new IllegalArgumentException("invalid experience evidence");
            }
        }
    }
}
